#include "ultrapool/core.hpp"
#include <cstdio>
#include <cstdlib>
#include <memory>
using namespace up;
namespace {
unsigned checks=0;
void verify(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"FAIL RITUAL/COPY: %s\n",why);std::exit(1);}}
void arena(Game& g){g=Game();g.phase=Phase::Aiming;g.target=1000000;g.world.pockets_enabled=false;Ball cue;cue.cue=true;cue.p=Vec(0,300);g.world.add(cue);g.snacks={};g.actions={};}
unsigned add(Game& g,BallKey key,unsigned level=1,int value=1,Vec p=Vec(100,0)){Ball b;b.def=builtin(id_of(key));b.level=static_cast<uint8_t>(level);b.def.base_score=value;b.p=p;g.world.add(b);return g.world.last_added;}
void pocket(Game& g,unsigned i){g.world.balls[i].active=false;g.world.balls[i].v=Vec();++g.world.metrics.ticks;g.world.events.push(EventKind::Pocketed,i,6,g.world.metrics.ticks,g.world.balls[i].generation);g.dispatch();}
void tick(Game& g,unsigned count){while(count--)g.update(tick_dt);}
unsigned actions(const Game& g,ActionKind kind){unsigned n=0;for(const auto& a:g.actions)n+=a.kind==kind;return n;}
}
unsigned ritual_tests(){
 auto storage=std::unique_ptr<Game>(new Game());Game& g=*storage;
 for(BallKey key:{BallKey::CANDLE,BallKey::OBSERVATORY,BallKey::PARROT,BallKey::HIT_BALL,BallKey::LUNA})verify(ball_supported(id_of(key)),"new content has native binding");
 arena(g);unsigned source=add(g,BallKey::CANDLE,3,2);pocket(g,source);verify(g.candles_pocketed==1 && g.ritual_strength==3 && !g.ritual_done,"Candle contributes own component level");verify(!g.pending_actions(),"partial pentagram is not an active carrier");tick(g,60);verify(g.ritual_progress>.999f,"pentagram line completes in one third second even at rest");
 for(unsigned i=0;i<3;++i){source=add(g,BallKey::CANDLE,i+1);pocket(g,source);}verify(g.candles_pocketed==4 && g.ritual_strength==9,"four Candles accumulate strength");source=add(g,BallKey::CANDLE,5);pocket(g,source);verify(g.ritual_strength==14 && actions(g,ActionKind::Ritual)==1 && g.pending_actions(),"fifth Candle schedules exactly one ritual after line animation");
 source=add(g,BallKey::CANDLE,5);pocket(g,source);verify(g.candles_pocketed==5 && g.ritual_strength==14 && actions(g,ActionKind::Ritual)==1,"sixth Candle cannot grow or restart ritual");tick(g,58);verify(!g.ritual_done,"ritual waits for the fifth line");tick(g,2);verify(g.ritual_done,"completed pentagram starts ritual");tick(g,36*14+2);verify(g.completed_ritual_strength==14 && !g.pending_actions(),"empty table still completes timed ritual and records total strength");
 arena(g);source=add(g,BallKey::CANDLE,2);g.world.balls[source].flaming=true;pocket(g,source);tick(g,18);verify(g.candles_pocketed==2 && g.ritual_strength==4,"flaming Candle contributes two separate callbacks");
 arena(g);unsigned recipient=add(g,BallKey::BREAD,1,1,Vec(120,-180));g.world.balls[recipient].locked=true;g.ritual_nudge();verify(actions(g,ActionKind::ModifierBall)==1,"ritual targets a locked but targetable object");for(const auto& a:g.actions)if(a.kind==ActionKind::ModifierBall)verify(a.flags==static_cast<unsigned>(Modifier::ShieldNudge) && a.multiplier==3,"ritual carries combined shield and triple nudge");
 for(unsigned n=0;n<1200 && !g.world.balls[recipient].shielded;++n)tick(g,1);verify(g.world.balls[recipient].shielded && !g.world.balls[recipient].locked,"arrival grants shield after unlocking for nudge");bool impulse=false;for(const auto& a:g.actions)if(a.kind==ActionKind::Impulse){verify(std::abs(a.impulse.length()-900)<.01f,"ritual momentum equals 600 times half of triple force");impulse=true;}verify(impulse,"ritual nudge uses delayed physical impulse");
 arena(g);recipient=add(g,BallKey::TUNGSTEN_BALL);add(g,BallKey::IMP);source=add(g,BallKey::BREAD);g.world.balls[source].falling=true;g.ritual_nudge();verify(!g.pending_actions(),"ritual excludes untargetable and falling candidates");
 arena(g);recipient=add(g,BallKey::BREAD);g.world.balls[recipient].shield_broken=true;g.ritual_nudge();for(unsigned n=0;n<1500 && g.pending_actions();++n)tick(g,1);verify(!g.world.balls[recipient].shielded && g.world.balls[recipient].v.length()>0,"broken shield cannot be restored but ritual still nudges");
 arena(g);unsigned parrot=add(g,BallKey::PARROT,3,8,Vec(-100,0));source=add(g,BallKey::BREAD);pocket(g,source);verify(!g.world.balls[parrot].parrot_used,"non-Pocket-effect object does not consume Parrot use");source=add(g,BallKey::GOLDEN_BALL,1,5);g.world.balls[source].mixed_with=id_of(BallKey::SMILEY);g.shots=2;pocket(g,source);verify(g.world.balls[parrot].parrot_used && g.money==2 && g.shots==3,"source effects run immediately while Parrot waits");verify(actions(g,ActionKind::RepeatEffect)==2,"Parrot snapshots both Pocket effects in identity order");tick(g,35);verify(g.money==2 && g.shots==3,"echo waits 0.2 seconds");tick(g,1);verify(g.money==8 && g.shots==6,"echo uses Parrot level for both components");source=add(g,BallKey::GOLDEN_BALL);pocket(g,source);verify(actions(g,ActionKind::RepeatEffect)==0,"second eligible pocket in one shot does not echo");
 g.phase=Phase::Aiming;g.angle=0;g.shoot();verify(!g.world.balls[parrot].parrot_used,"real player shoot event resets Parrot before physics advances");source=add(g,BallKey::GOLDEN_BALL);pocket(g,source);verify(actions(g,ActionKind::RepeatEffect)==1,"new shot permits another echo");
 arena(g);parrot=add(g,BallKey::PARROT,2);g.world.balls[parrot].flaming=true;source=add(g,BallKey::GOLDEN_BALL);pocket(g,source);tick(g,60);verify(g.money==6,"flaming Parrot global repeat respects use guard and does not double direct echoes");
 arena(g);parrot=add(g,BallKey::PARROT,2,10);source=add(g,BallKey::LICH,1,3);pocket(g,source);unsigned lich_echoes=0;for(const auto& a:g.actions)if(a.kind==ActionKind::RepeatEffect){verify(a.call.level==2 && a.call.receiver.index==parrot && a.call.pocket==6,"echo uses Parrot as source and virtual pocket origin");++lich_echoes;}verify(lich_echoes==1,"one Lich echo queued");
 arena(g);unsigned observer=add(g,BallKey::OBSERVATORY,4,2,Vec(-150,100));source=add(g,BallKey::CHICKEN,3,11);g.world.balls[source].mixed_with=id_of(BallKey::GOLDEN_BALL);g.world.balls[source].temp_value=2;pocket(g,source);verify(g.world.count==4,"Observatory makes immediate body before self pocket effect");Ball& copy=g.world.balls[3];verify(copy.def.id==id_of(BallKey::CHICKEN) && copy.mixed_with==id_of(BallKey::GOLDEN_BALL) && copy.def.base_score==9 && copy.base_value==9 && copy.temp_value==0,"Observatory preserves ordered identities and ceiling-scaled raw value");verify(copy.level==1 && copy.fleeting && copy.owner==-1,"copy becomes temporary level one and fleeting after Spawn");unsigned level3eggs=0;for(const auto& a:g.actions)if(a.kind==ActionKind::Spawn && a.snapshot.def.id==id_of(BallKey::EGG)){verify(a.snapshot.level==3,"Observatory Spawn sees original level before level-one assignment");++level3eggs;}verify(level3eggs==2,"copied Chicken Spawn and original Chicken Pocket each lay one Egg");
 source=add(g,BallKey::BREAD);g.world.balls[3].falling=true;pocket(g,source);verify(g.world.balls[3].active && !g.world.balls[3].gone,"original break_for_round guard preserves a fleeting copy already falling");
 arena(g);observer=add(g,BallKey::OBSERVATORY,3);source=add(g,BallKey::BREAD,5,13);g.world.balls[source].fleeting=true;pocket(g,source);verify(g.world.count==3,"Observatory refuses fleeting sources and cannot loop");
 arena(g);add(g,BallKey::OBSERVATORY,5);source=add(g,BallKey::BREAD,4,13);pocket(g,source);verify(g.world.balls[3].def.base_score==13 && g.world.balls[3].level==1,"level-five Observatory copies full value at level one");
 arena(g);add(g,BallKey::OBSERVATORY);source=add(g,BallKey::BREAD);g.world.balls[source].def.base_score=-3;pocket(g,source);verify(g.world.balls[3].def.base_score==0,"negative Observatory fractions use ceiling rather than truncation or floor");
 arena(g);add(g,BallKey::OBSERVATORY,3);source=add(g,BallKey::BREAD,5,10);pocket(g,source);verify(g.world.balls[3].def.base_score==7,"preserved binary double expression ceil(10 * (0.2 * 3)) produces seven; original runtime parity remains to verify");
 arena(g);add(g,BallKey::OBSERVATORY,2);source=add(g,BallKey::GHOST,3,8);g.world.balls[source].ghost_used=true;g.world.balls[source].shielded=false;pocket(g,source);verify(g.world.balls[3].ghost_used && g.world.balls[3].shielded,"new Observatory Ghost gets its own Spawn variable state instead of inheriting source use");
 for(unsigned level=1;level<=5;++level){arena(g);unsigned luna=add(g,BallKey::LUNA,level);g.angle=.7f;g.shoot();bool found=false;for(const auto& a:g.actions)if(a.kind==ActionKind::Impulse && a.target==luna){verify(std::abs(a.impulse.length()-600*(.7f+.4f*level))<.01f,"Luna uses verified level force");verify(a.impulse.unit().dot(Vec(std::cos(.7f),std::sin(.7f)))>.999f,"Luna follows player direction");found=true;}verify(found,"player shoot dispatches Luna immediately");}
 arena(g);unsigned hit=add(g,BallKey::HIT_BALL,5);g.shoot();unsigned impulses=0;for(const auto& a:g.actions)if(a.kind==ActionKind::Impulse && a.target==hit){verify(std::abs(a.impulse.length()-600)<.01f,"Hit Ball force does not scale with level");++impulses;}verify(impulses==1,"Hit Ball receives one real shoot callback");
 arena(g);source=add(g,BallKey::LUNA,2);g.world.balls[source].mixed_with=id_of(BallKey::HIT_BALL);g.world.balls[source].flaming=true;g.shoot();verify(actions(g,ActionKind::Impulse)==2 && actions(g,ActionKind::RepeatEffect)==2,"mixed flaming shot effects dispatch both sides and repeats");tick(g,18);verify(actions(g,ActionKind::Impulse)==2,"flaming Shot repeats create second pair of delayed impulses");
 g.candles_pocketed=5;g.ritual_strength=17;g.completed_ritual_strength=17;g.begin_round();verify(!g.candles_pocketed && !g.ritual_strength && !g.ritual_done && !g.completed_ritual_strength,"new round resets ritual state");
 std::printf("Ritual, echo and shot checks: %u\n",checks);return checks;
}
